<?php $title="Add Teacher";require "../includes/header.php";$deps=$pdo->query("SELECT * FROM departments")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$_POST['department_id']=(int)$_POST['department_id'];$s=$pdo->prepare("INSERT INTO teachers(teacher_id,name,email,phone,department_id,designation) VALUES(?,?,?,?,?,?)");$s->execute([$_POST['teacher_id'],$_POST['name'],$_POST['email'],$_POST['phone'],$_POST['department_id'],$_POST['designation']]);header("Location:index.php");exit;}?><h2>Add Teacher</h2><div class="card p-4"><form method="post" class="row g-3"><div class="col-md-3"><label>ID</label><input name="teacher_id" class="form-control" required></div><div class="col-md-5"><label>Name</label><input name="name" class="form-control" required></div><div class="col-md-4"><label>Email</label><input type="email" name="email" class="form-control"></div><div class="col-md-4"><label>Phone</label><input name="phone" class="form-control"></div><div class="col-md-4"><label>Department</label><select name="department_id" class="form-select"><?php foreach($deps as $d):?><option value="<?=$d['id']?>"><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Designation</label><input name="designation" class="form-control"></div><div><button class="btn btn-primary">Save</button></div></form></div><?php require "../includes/footer.php";?>